<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Download, Search, Wallet, Money, Warning, Connection } from '@element-plus/icons-vue'
import { useApp } from '../store'
import { api, download, query } from '../api'
import { money, quantity, today, monthStart } from '../utils'
import DataTable from '../components/DataTable.vue'
import Documents from './Documents.vue'
const app = useApp(), route = useRoute(), side = ref(String(route.query.side || 'ar')), view = ref(String(route.query.view || 'bills')), partner = ref<any>(), search = ref(''), openOnly = ref(true), dates = ref([monthStart(), today()])
const bills = ref<any[]>([]), vouchers = ref<any[]>([]), aging = ref<any[]>([]), writeoffs = ref<any[]>([]), partners = ref<any[]>([]), statement = ref<any>(null), busy = ref(false), saving = ref(false)
const allocationOpen = ref(false), selectedVoucher = ref<any>(), allocationRows = ref<any[]>([]), offsetOpen = ref(false)
const offset = reactive<any>({ positive_bill_id: undefined, negative_bill_id: undefined, amount: '' })
const canWrite = computed(() => app.can('finance.approve') && app.writable('finance'))
async function load() { busy.value = true; try { const p = query({ side: side.value, partner_id: partner.value }); const results = await Promise.all([api('/finance/bills?' + p), api('/finance/settlements?' + p)]); bills.value = results[0].items; vouchers.value = results[1].items; if (view.value === 'aging') aging.value = (await api('/finance/aging?side=' + side.value)).items; if (view.value === 'writeoffs') writeoffs.value = (await api('/finance/writeoffs?side=' + side.value)).items.map((r: any) => ({ ...r, writeoff_status: r.reversed ? 'reversed' : 'completed' })); if (view.value === 'statement' && partner.value) statement.value = await api('/finance/statement?' + query({ side: side.value, partner_id: partner.value, start: dates.value?.[0], end: dates.value?.[1] })); else statement.value = null } catch {} finally { busy.value = false } }
async function loadPartners() { try { partners.value = (await api('/masters/' + (side.value === 'ar' ? 'customer' : 'supplier'))).items } catch {} }
watch(side, () => { partner.value = undefined; loadPartners(); load() }); watch([view, partner], load); watch(() => app.tick, load); onMounted(() => { load(); loadPartners() })
watch(() => route.query.view, value => { if(value) view.value = String(value) })
watch(() => route.query.side, value => { if(value) side.value = String(value) })
const remaining = computed(() => bills.value.reduce((sum, b) => sum + Number(b.remaining), 0))
const overdue = computed(() => bills.value.filter(b => b.due_date < today() && Number(b.remaining) > 0).reduce((sum, b) => sum + Number(b.remaining), 0))
const advance = computed(() => vouchers.value.reduce((sum, v) => sum + Number(v.remaining), 0))
const rows = computed(() => { let result = view.value === 'bills' ? bills.value.filter(b => !openOnly.value || Number(b.remaining) !== 0) : view.value === 'settlements' ? vouchers.value : view.value === 'aging' ? aging.value : view.value === 'writeoffs' ? writeoffs.value : statement.value?.items || []; if (search.value) result = result.filter((r: any) => JSON.stringify(r).includes(search.value)); return result })
const columns = computed(() => {
  const monetary = (key: string, label: string) => ({ key, label, type: 'money', minWidth: 115, hidden: !app.amountVisible })
  if (view.value === 'aging') return [{ key: 'partner_name', label: '往来单位', minWidth: 160 }, ...[['current', '未到期'], ['days_1_30', '1–30 天'], ['days_31_60', '31–60 天'], ['days_61_90', '61–90 天'], ['days_91_180', '91–180 天'], ['days_180_plus', '180 天以上'], ['credit', '退货贷项'], ['total', '账款合计']].map(([key, label]) => monetary(key, label))]
  if (view.value === 'statement') return [{ key: 'date', label: '日期', width: 108 }, { key: 'number', label: '单据编号', type: 'link', minWidth: 200 }, { key: 'kind_name', label: '业务类型', minWidth: 130 }, monetary('charge', '账务发生'), monetary('paid', '收付款'), monetary('balance', '往来余额')]
  if (view.value === 'writeoffs') return [{ key: 'settlement_number', label: '收付款单号', minWidth: 210 }, { key: 'bill_number', label: '被核销单号', minWidth: 205 }, { key: 'partner_name', label: '往来单位', minWidth: 150 }, monetary('amount', '核销金额'), { key: 'writeoff_status', label: '状态', type: 'status', width: 90 }, { key: 'operator', label: '操作人' }, { key: 'created_at', label: '核销时间', type: 'datetime', minWidth: 175 }]
  const result: any[] = [{ key: 'number', label: view.value === 'bills' ? '业务单号' : '收付款单号', type: 'link', minWidth: 210 }, { key: 'partner_name', label: side.value === 'ar' ? '客户名称' : '供应商名称', minWidth: 160 }, { key: 'date', label: '业务日期', width: 108 }, monetary('amount', '发生金额'), monetary(view.value === 'bills' ? 'settled' : 'allocated', '已核销'), monetary('remaining', '未核销余额')]
  if (view.value === 'bills') result.push({ key: 'due_date', label: '到期日期', width: 108 }, { key: 'overdue_days', label: '逾期天数', width: 90 }); return result
})
const availableVouchers = computed(() => vouchers.value.filter(v => Number(v.remaining) !== 0))
const voucher = computed(() => vouchers.value.find(v => v.id === selectedVoucher.value))
const allocationTotal = computed(() => allocationRows.value.filter(r => r.checked).reduce((n, r) => n + Number(r.use_amount || 0), 0))
function allocate(row?: any) { selectedVoucher.value = row?.id || availableVouchers.value[0]?.id; allocationOpen.value = true; prepareAllocations() }
function prepareAllocations() { const v = voucher.value; if (!v) { allocationRows.value = []; return }; let available = Math.abs(Math.round(Number(v.remaining) * 100)); allocationRows.value = bills.value.filter(b => b.partner_id === v.partner_id && Number(b.remaining) * Number(v.remaining) > 0).sort((a, b) => a.due_date.localeCompare(b.due_date) || a.id - b.id).map(b => { const n = Math.min(available, Math.abs(Math.round(Number(b.remaining) * 100))); available -= n; return { ...b, checked: n > 0, use_amount: (n / 100).toFixed(2) } }) }
async function confirmAllocation() { const selected = allocationRows.value.filter(r => r.checked && Number(r.use_amount) > 0); if (!selected.length) { ElMessage.warning('请选择账单并填写核销金额'); return }; saving.value = true; try { await api('/finance/writeoff', 'POST', { settlement_id: selectedVoucher.value, allocations: selected.map(r => ({ bill_id: r.id, amount: String(r.use_amount) })) }); ElMessage.success('往来核销已完成'); allocationOpen.value = false; app.changed() } catch {} finally { saving.value = false } }
const positiveBills = computed(() => bills.value.filter(b => Number(b.remaining) > 0))
const negativeBills = computed(() => bills.value.filter(b => Number(b.remaining) < 0 && (!offset.positive_bill_id || b.partner_id === positiveBills.value.find(p => p.id === offset.positive_bill_id)?.partner_id)))
function openOffset() { Object.assign(offset, { positive_bill_id: undefined, negative_bill_id: undefined, amount: '' }); offsetOpen.value = true }
function offsetAmount() { const p = positiveBills.value.find(b => b.id === offset.positive_bill_id), n = negativeBills.value.find(b => b.id === offset.negative_bill_id); offset.amount = p && n ? Math.min(Number(p.remaining), -Number(n.remaining)).toFixed(2) : '' }
async function saveOffset() { saving.value = true; try { await api('/finance/offset', 'POST', { ...offset, amount: String(offset.amount) }); ElMessage.success('往来冲账完成'); offsetOpen.value = false; app.changed() } catch {} finally { saving.value = false } }
async function undo(row: any) { try { const result = await ElMessageBox.prompt('仅撤销核销关系，收付款单继续保留。', '撤销核销', { inputPlaceholder: '请填写原因', inputValidator: v => !!v?.trim() || '原因不能为空' }); await api('/finance/writeoffs/' + row.id + '/reverse', 'POST', { reason: result.value }); app.changed(); ElMessage.success('核销已撤销') } catch {} }
function exportRows() { download('/export?' + query({ type: view.value, side: side.value, partner_id: partner.value, start: dates.value?.[0], end: dates.value?.[1] })) }
function create(kind: string) { app.openDoc(0, kind, partner.value ? { kind, partner_id: partner.value, date: today(), data: {}, items: [], amount: '' } : null) }
</script>
<template>
  <div class="page-head"><div><h1>往来管理</h1><p>应收应付、收款付款与核销相互关联，每一笔余额都能追溯。</p></div><div class="page-actions"><el-button v-if="canWrite" :icon="Connection" @click="allocate()">往来核销</el-button><el-dropdown v-if="app.can('finance.edit')" @command="create" trigger="click"><el-button type="primary" :icon="Plus" :disabled="!app.writable('finance')">新建收付款</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item :command="side === 'ar' ? 'ar_receipt' : 'ap_payment'">{{ side === 'ar' ? '客户收款 / 预收' : '供应商付款 / 预付' }}</el-dropdown-item><el-dropdown-item :command="side === 'ar' ? 'ar_refund' : 'ap_refund'">{{ side === 'ar' ? '客户退款' : '供应商退款' }}</el-dropdown-item><el-dropdown-item :command="side === 'ar' ? 'opening_ar' : 'opening_ap'" divided>{{ side === 'ar' ? '期初应收' : '期初应付' }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></div>
  <div class="finance-heading"><el-radio-group v-model="side" size="large"><el-radio-button value="ar">客户应收</el-radio-button><el-radio-button value="ap">供应商应付</el-radio-button></el-radio-group><span class="muted">{{ side === 'ar' ? '销售出库产生应收，收款与退货冲减余额' : '采购入库产生应付，付款与退货冲减余额' }}</span></div>
  <div class="metric-grid finance-metrics"><div class="metric-card"><div class="metric-label">{{ side === 'ar' ? '待收账款' : '待付账款' }}<div class="metric-icon"><el-icon><Wallet/></el-icon></div></div><div class="metric-value"><small>¥</small>{{ app.amountVisible ? money(remaining) : '—' }}</div><div class="metric-footer">当前账单净余额 · 含退货贷项</div></div><div class="metric-card"><div class="metric-label">逾期未核销<div class="metric-icon orange"><el-icon><Warning/></el-icon></div></div><div class="metric-value"><small>¥</small>{{ app.amountVisible ? money(overdue) : '—' }}</div><div class="metric-footer">到期日早于今天的正向余额</div></div><div class="metric-card"><div class="metric-label">{{ side === 'ar' ? '可用预收款' : '可用预付款' }}<div class="metric-icon green"><el-icon><Money/></el-icon></div></div><div class="metric-value"><small>¥</small>{{ app.amountVisible ? money(advance) : '—' }}</div><div class="metric-footer">已收付但尚未核销的资金</div></div></div>
  <div class="subnav panel mb16"><button v-for="v in [{k:'bills',n:'往来账单'},{k:'settlements',n:'收付款 / 预收预付'},{k:'aging',n:'账龄分析'},{k:'statement',n:'往来对账'},{k:'writeoffs',n:'核销记录'},{k:'documents',n:'资金单据'}]" :key="v.k" :class="{selected:view === v.k}" @click="view = v.k">{{ v.n }}</button></div>
  <Documents v-if="view === 'documents'" module="finance" embedded/>
  <section v-else class="panel"><div class="filter-row"><el-select v-model="partner" :placeholder="view === 'statement' ? '请选择对账单位' : '全部往来单位'" filterable clearable style="width:210px"><el-option v-for="p in partners" :key="p.id" :label="p.name" :value="p.id"/></el-select><el-input v-if="view !== 'statement'" v-model="search" :prefix-icon="Search" placeholder="筛选单据或往来单位" clearable/><el-date-picker v-if="view === 'statement'" v-model="dates" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" @change="load"/><el-checkbox v-if="view === 'bills'" v-model="openOnly">仅未核销</el-checkbox><el-button type="primary" plain @click="load">查询</el-button><div class="spacer"></div><el-button v-if="view === 'bills' && canWrite" @click="openOffset">退货贷项冲账</el-button><el-button v-if="view !== 'writeoffs'" :icon="Download" :disabled="view === 'statement' && !partner" @click="exportRows">导出</el-button></div>
    <div v-if="view === 'statement' && statement && app.amountVisible" class="summary-strip" style="border-bottom:1px solid #edf1f6"><span><label>期初余额</label><strong>¥ {{ money(statement.opening) }}</strong></span><span><label>期间发生</label><strong>¥ {{ money(statement.charges) }}</strong></span><span><label>期间收付款</label><strong>¥ {{ money(statement.paid) }}</strong></span><span><label>期末余额</label><strong>¥ {{ money(statement.closing) }}</strong></span></div>
    <DataTable :rows="rows" :columns="columns" :loading="busy" :empty="view === 'statement' && !partner ? '选择往来单位和日期，生成对账单' : '暂无往来记录，审核业务单据后自动生成账款'" @open="id => app.openDoc(id)"><template v-if="view === 'settlements' || view === 'writeoffs'" #actions="{ row }"><el-button v-if="view === 'settlements' && canWrite" link type="primary" :disabled="Number(row.remaining) === 0" @click="allocate(row)">核销</el-button><el-button v-if="view === 'writeoffs' && canWrite && !row.reversed" link type="danger" @click="undo(row)">撤销核销</el-button></template></DataTable>
  </section>
  <el-dialog v-model="allocationOpen" title="往来核销" width="880px" destroy-on-close><p class="muted mb16">选择可用收付款单，按同一往来单位、同一方向核销；支持部分核销与多张账单。</p><el-select v-model="selectedVoucher" filterable placeholder="请选择有未分配余额的收付款单" @change="prepareAllocations"><el-option v-for="v in availableVouchers" :key="v.id" :value="v.id" :label="v.number + ' · ' + v.partner_name + ' · 可用 ¥ ' + money(v.remaining)"/></el-select><div class="doc-toolbar"><span class="muted">{{ voucher?.partner_name || '尚未选择收付款单' }}</span><el-button size="small" @click="prepareAllocations">按账期自动分配</el-button></div><el-table :data="allocationRows" max-height="320"><el-table-column width="45"><template #default="{row}"><el-checkbox v-model="row.checked"/></template></el-table-column><el-table-column prop="number" label="账单编号" min-width="205"/><el-table-column prop="due_date" label="到期日期" width="115"/><el-table-column label="待核销金额" width="140" align="right"><template #default="{row}">{{ money(row.remaining) }}</template></el-table-column><el-table-column label="本次核销" width="160"><template #default="{row}"><el-input v-model="row.use_amount" inputmode="decimal" :disabled="!row.checked"><template #prefix>¥</template></el-input></template></el-table-column></el-table><div class="summary-strip mt16"><span><label>可用资金</label><strong>¥ {{ money(Math.abs(Number(voucher?.remaining || 0))) }}</strong></span><span><label>本次核销</label><strong>¥ {{ money(allocationTotal) }}</strong></span></div><template #footer><el-button @click="allocationOpen = false">取消</el-button><el-button type="primary" :disabled="!selectedVoucher || !allocationTotal || !canWrite" :loading="saving" @click="confirmAllocation">确认核销</el-button></template></el-dialog>
  <el-dialog v-model="offsetOpen" title="退货贷项冲账" width="600px"><div class="hint-box mb16">用同一往来单位的退货贷项抵扣正向应收 / 应付。原单退货审核时会优先自动抵扣原账单。</div><el-form label-position="top"><el-form-item label="正向账单"><el-select v-model="offset.positive_bill_id" filterable @change="offset.negative_bill_id = undefined; offsetAmount()"><el-option v-for="b in positiveBills" :key="b.id" :value="b.id" :label="b.number + ' · ' + b.partner_name + ' · ¥ ' + money(b.remaining)"/></el-select></el-form-item><el-form-item label="退货贷项"><el-select v-model="offset.negative_bill_id" filterable @change="offsetAmount"><el-option v-for="b in negativeBills" :key="b.id" :value="b.id" :label="b.number + ' · ¥ ' + money(b.remaining)"/></el-select></el-form-item><el-form-item label="本次冲账金额"><el-input v-model="offset.amount" inputmode="decimal"><template #prefix>¥</template></el-input></el-form-item></el-form><template #footer><el-button @click="offsetOpen = false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!offset.positive_bill_id || !offset.negative_bill_id || Number(offset.amount) <= 0" @click="saveOffset">确认冲账</el-button></template></el-dialog>
</template>
<style scoped>.finance-heading{display:flex;align-items:center;gap:22px;margin-bottom:20px}.finance-metrics{grid-template-columns:repeat(3,1fr)}@media(max-width:700px){.finance-heading{align-items:flex-start;flex-direction:column;gap:10px}.finance-metrics{grid-template-columns:1fr}}</style>
